static long compressTimeBucket(long timeBucket, int dayStep) {
    long newTimeBucket;
    if (dayStep == 1) {
        newTimeBucket = timeBucket / 1000000;
    } else {
        long day = timeBucket % 1000000;
        day = day - day % dayStep;
        newTimeBucket = timeBucket / 1000000 * 1000000 + day;
    }
