public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder builder = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char ch = str.charAt(i);
        switch (ch) {
            case '\\':
                builder.append(ch);
                if (i + 1 < len) {
                    builder.append(str.charAt(i + 1));
                    i++;
                }
                break;
            case '\'':
            case '"':
            case 'b':
            case 'f':
            case 'n':
            case 'r':
            case 't':
                builder.append(ESCAPE_CODES.get(ch));
                break;
            default:
                if (ch >= 0x20 && ch < 0x7F) {
                    builder.append(ch);
                } else {
                    builder.append(String.format("\\u%04x", (int) ch));
                }
        }
    }
    return builder.toString();
}
