        Set<V> smallerSet = set1;
        Set<V> biggerSet = set2;

        // Create a new set to store the intersection
        Set<V> intersection = new HashSet<>();

        // Iterate over smaller set
        for (V element : smallerSet) {
            // If element is also in bigger set, add to intersection
            if (biggerSet.contains(element)) {
                intersection.add(element);
            }
        }

        return intersection;
    } else {
