private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    // Initialize the list of minimal separators for every edge in the graph
    Map<E, List<Pair<Integer, Integer>>> minimalSeparators = new HashMap<>();
    for (E edge : graph.edgeSet()) {
        minimalSeparators.put(edge, new ArrayList<>());
    }

    // Compute the minimal separators for each edge in the neighborhood of every vertex
    for (V vertex : graph.vertexSet()) {
        // Get the neighborhood of the vertex
        Set<E> neighborhood = graph.edgesOf(vertex);

        // Iterate over the edges in the neighborhood
        for (E edge1 : neighborhood) {
            V vertex1 = edge1.getStart();
            if (vertex1.equals(vertex)) {
                // Edge starts at the vertex, so get the end vertex of the edge
                vertex1 = edge1.getEnd();
            }

            // Get the neighbors of the end vertex
            Set<E> neighbors = graph.edgesOf(vertex1);

            // Iterate over the neighbors of the end vertex
            for (E edge2 : neighbors) {
                V vertex2 = edge2.getStart();
                if (vertex2.equals(vertex1)) {
                    // Edge starts at the end vertex, so get the end vertex of the edge
                    vertex2 = edge2.getEnd();
                }

                // Check if the vertex is not the vertex of the edge being processed
                if (!vertex2.equals(vertex)) {
                    // Compute the minimal separator between the two vertices
                    List<E> minimalSeparator = computeMinimalSeparator(vertex1, vertex2);

                    // Add the minimal separator to the list of minimal separators for the edge
                    minimalSeparators.get(edge1).add(new Pair<>(minimalSeparator, edge2));
                }
            }
        }
    }

    // Extract the minimal separators for every edge from the map
    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparators = new ArrayList<>();
    for (E edge : graph.edgeSet()) {
        globalSeparators.add(new Pair<>(minimalSeparators.get(edge), edge));
    }

    // Return the list of minimal separators
    return globalSeparators;
}

