    List<Integer> minimalSeparators = new ArrayList<>();

    // Get the neighbors of the two vertices
    Set<E> neighbors1 = graph.edgesOf(vertex1);
    Set<E> neighbors2 = graph.edgesOf(vertex2);

    // Iterate over the neighbors of the two vertices
    for (E edge1 : neighbors1) {
