private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    // Compute the separator list for every edge in the graph
    List<Pair<List<Pair<Integer, Integer>>, E>> separatorList = new ArrayList<>();
    for (E e : graph.edgeSet()) {
        // Get the neighborhood of the edge
        Neighborhood<V> neighborhood = graph.neighborhoodOf(e);
        // Compute the minimal separators of the edge in the neighborhood
        List<Pair<List<Pair<Integer, Integer>>, E>> edgeSeparatorList = computeLocalSeparatorList(neighborhood, e);
        // Add the edge separators to the global separator list
