private List<Pair<List<Pair<Integer, Integer>>, E>> computeLocalSeparatorList(Neighborhood<V> neighborhood, E edge) {
    // Compute the separator list for every vertex in the neighborhood
    List<Pair<List<Pair<Integer, Integer>>, V>> separatorList = new ArrayList<>();
    for (V v : neighborhood.vertices()) {
        // Compute the separator list of the vertex
        List<Pair<List<Pair<Integer, Integer>>, V>> vertexSeparatorList = computeVertexSeparatorList(neighborhood, v);
        // Add the vertex separators to the global separator list
        separatorList.addAll(vertexSeparatorList);
