private List<Pair<List<Pair<Integer, Integer>>, V>> computeVertexSeparatorList(Neighborhood<V> neighborhood, V vertex) {
    // Get the separator list of the vertex
    List<Edge> vertexSeparators = neighborhood.separatorsOf(vertex);
    // Compute the minimal separators of the vertex
    List<Pair<List<Pair<Integer, Integer>>, V>> vertexSeparatorList = new ArrayList<>();
    for (Edge e : vertexSeparators) {
