 */
private List<Pair<List<Pair<Integer, Integer>>, E>> computeEdgeSeparators(List<Pair<List<Pair<Integer, Integer>>, V>> separatorList, E edge) {
    // Compute the minimal separators of the edge
    List<Pair<List<Pair<Integer, Integer>>, E>> edgeSeparators = new ArrayList<>();
    for (Pair<List<Pair<Integer, Integer>>, V> vertexSeparator : separatorList) {
        // Get the vertex separator list
        List<Pair<Integer, Integer>> vertexSeparatorList = vertexSeparator.getFirst();
        // Compute the minimal separators of the vertex separator
        List<Pair<Integer, Integer>> edgeSeparatorList = computeEdgeSeparator(vertexSeparatorList, edge);
        // Add the edge separator to the list of edge separators
        edgeSeparators.add(new Pair<>(edgeSeparatorList, edge));
