 * @param vertexSeparator the vertex separator used to compute the minimal separator
 * @param edge the edge for which to compute the minimal separator
 * @return the minimal separator of the edge in the vertex separator
 */
private List<Pair<Integer, Integer>> computeEdgeSeparator(List<Pair<Integer, Integer>> vertexSeparator, E edge) {
    // Compute the minimal separator of the edge
    List<Pair<Integer, Integer>> edgeSeparator = new ArrayList<>();
    // Traverse the vertex separator and find the matching edge separator
    for (Pair<Integer, Integer> pair : vertexSeparator) {
        // If the edge is found, add it to the edge separator list
        if (pair.getFirst().equals(edge.getFirst()) && pair.getSecond().equals(edge.getSecond())) {
            edgeSeparator.add(pair);
            break;
        }
    }
    // Return the minimal separator of the edge
    return edgeSeparator;
}

/**
 * Computes the global separator list of the {@code graph}. More precisely, for every edge $e$ in the $G = (V, E)$ computes list of minimal separators $S_e$ in the neighborhood of $e$ and then concatenates these lists. Note: the result may contain duplicates.
 *
 * @return the list of minimal separators of every edge $e$ in the inspected graph
 */
private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    // Step 1: get the adjacency list of the graph
    Map<Integer, List<Edge>> adjList = graph.getAdjacencyList();

    // Step 2: initialize the global separator list with an empty list
    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();

    // Step 3: for each edge $e$ in the graph
    for (Edge e : adjList.values()) {
        // Step 3.1: get the vertices of the edge $e$
        int u = e.getFirst();
        int v = e.getSecond();

        // Step 3.2: get the neighbors of the vertices $u$ and $v$
        List<Integer> neighborsU = adjList.get(u);
        List<Integer> neighborsV = adjList.get(v);

        // Step 3.3: get the minimal separators $S_e$ in the neighborhood of $e$
        List<List<Pair<Integer, Integer>>> minimalSeparators = new ArrayList<>();
        for (Integer neighborU : neighborsU) {
            if (neighborU != v) {
                List<Pair<Integer, Integer>> separatorUV = new ArrayList<>();
                separatorUV.add(new Pair<>(u, v));
                minimalSeparators.add(separatorUV);
            }
        }
        for (Integer neighborV : neighborsV) {
            if (neighborV != u) {
                List<Pair<Integer, Integer>> separatorUV = new ArrayList<>();
                separatorUV.add(new Pair<>(u, v));
                minimalSeparators.add(separatorUV);
            }
        }

        // Step 3.4: concatenate the minimal separators $S_e$
        List<Pair<Pair<Integer, Integer>, E>> concatenatedSeparators = new ArrayList<>();
        for (List<Pair<Integer, Integer>> minimalSeparator : minimalSeparators) {
            Pair<Integer, Integer> uv = minimalSeparator.get(0);
            concatenatedSeparators.add(new Pair<>(uv, e));
        }

        // Step 3.5: add the concatenated separators to the global separator list
        globalSeparatorList.add(new Pair<>(concatenatedSeparators, e));
    }

    // Step 4: return the global separator list
    return globalSeparatorList;
}

