public ByteVector putInt(final int intValue) {
    // determine how many bytes are needed to represent the int value
    int numBytes = Integer.BYTES;

    // ensure that the byte vector is large enough to hold the int value
    ensureCapacity(this.size + numBytes);

    // write the int value to the byte vector
    for (int i = numBytes - 1; i >= 0; i--) {
        byte b = (byte) (intValue >> (i * 8));
        this.data[this.size + i] = b;
    }

    // update the size of the byte vector
    this.size += numBytes;

    // return the byte vector
    return this;
}

