    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");

    // Calculate the number of steps up the directory tree we need to go
    int numStepsUp = 0;
    for (String part : relativePathParts) {
        if ("..".equals(part)) {
            numStepsUp++;
        }
    }

    // Create a new path builder
    StringBuilder newPath = new StringBuilder();

    // Iterate over the path parts and calculate the new path
    for (int i = 0; i < pathParts.length - numStepsUp; i++) {
        newPath.append(pathParts[i]).append("/");
    }
    for (int i = 0; i < relativePathParts.length; i++) {
        if (!"..".equals(relativePathParts[i])) {
            newPath.append(relativePathParts[i]).append("/");
        }
    }

    // Remove any trailing slashes
    if (newPath.length() > 0 && newPath.charAt(newPath.length() - 1) == '/') {
        newPath.deleteCharAt(newPath.length() - 1);
    }

    // Return the new path
    return newPath.toString();
}

