private static List<ThreadSnapshot> parseThreadSnapshots(DataInputStream dis) throws IOException {
    // Skip the header
    for (int i = 0; i < 5; i++) {
        dis.readInt();
    }

    // Read the number of thread snapshots
    int numThreadSnapshots = dis.readInt();

    // Read each thread snapshot
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    for (int i = 0; i < numThreadSnapshots; i++) {
        int numThreads = dis.readInt();
        List<Thread> threads = new ArrayList<>();
        for (int j = 0; j < numThreads; j++) {
            int threadId = dis.readInt();
            String threadName = dis.readUTF();
            long stackTraceId = dis.readLong();
            Thread thread = new Thread(threadId, threadName, stackTraceId);
            threads.add(thread);
        }
        int numSamples = dis.readInt();
        List<Sample> samples = new ArrayList<>();
        for (int j = 0; j < numSamples; j++) {
            long timestamp = dis.readLong();
            int state = dis.readInt();
            String stackTrace = dis.readUTF();
            Sample sample = new Sample(timestamp, state, stackTrace);
            samples.add(sample);
        }
        ThreadSnapshot threadSnapshot = new ThreadSnapshot(threads, samples);
        threadSnapshots.add(threadSnapshot);
    }
    return threadSnapshots;
}

private static ThreadSnapshot findThreadSnapshot(List<ThreadSnapshot> threadSnapshots, long startTime, long endTime) {
    for (ThreadSnapshot threadSnapshot : threadSnapshots) {
        if (threadSnapshot.getStartTime() <= startTime && threadSnapshot.getEndTime() >= endTime) {
            return threadSnapshot;
        }
    }
    return null;
}
