public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();

    try (RandomAccessFile raf = new RandomAccessFile(file, "r");) {
        // Get the file size
        long fileSize = raf.length();
        // Read the header data
        HeapDumpFile.Header header = HeapDumpFile.readHeader(raf);
        // Get the number of threads
        int numThreads = (int) header.totalCount;
        // Iterate over the threads
        for (int i = 0; i < numThreads; i++) {
            // Read the thread data
            HeapDumpFile.ThreadData threadData = HeapDumpFile.readThreadData(raf, fileSize);
            // Check if the thread is alive or not
            boolean isAlive = threadData.alive;
            // Get the thread location
            int threadStartIdx = (int) threadData.startIdx;
            int threadEndIdx = (int) threadData.endIdx;
            // Check if the thread is in the specified time range
            boolean isThreadInRange = false;
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (timeRange.getStartTime() <= threadStartIdx && threadEndIdx <= timeRange.getEndTime()) {
                    isThreadInRange = true;
                    break;
                }
            }
            // Add the snapshot if the thread is in the specified time range
            if (isThreadInRange) {
                ThreadSnapshot threadSnapshot = new ThreadSnapshot(isAlive, threadStartIdx, threadEndIdx);
                snapshots.add(threadSnapshot);
            }
        }
    }

    return snapshots;
}
